#include "wled.h"

#ifdef ARDUINO_ARCH_ESP32

#include <WiFi.h>
#include <WiFiUdp.h>
#include <HTTPClient.h>

#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>

#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"

/*
================================================================================
SHYNETYME.WORKS — WLED HOST USERMOD
Target: WLED v16.0.1 / classic ESP32 / esp32dev

ROLE
----
PHONE/WEB APP  --Bluetooth-->  HOST ESP32
HOST ESP32     --Wi-Fi AP-->    CLIENT 1 + CLIENT 2
CLIENTS have NO Bluetooth. The HOST is authoritative.

IMPORTANT:
- This is a WLED usermod, not a replacement LED engine.
- WLED remains responsible for effects, matrices, LED timing, data pin, etc.
- The host's normal effect/color/brightness state is mirrored to clients through
  WLED's native UDP sync transport.
- Client identity/password below are application-level registration credentials.
- Host Wi-Fi AP itself is intentionally OPEN, as requested.

===============================================================================
USER CONFIG — HOST
Change only this block if you intentionally rename the host or clients.
===============================================================================
*/

static constexpr char HOST_BLE_NAME[] = "Captain Shynetyme.Worker";
static constexpr char HOST_AP_SSID[]  = "Captain Shynetyme.Worker";
static constexpr char HOST_AP_PASS[]  = "MacDaddy310";         // WPA2 Wi-Fi AP

static constexpr char CLIENT1_NAME[]  = "ShynetymeplayerOne";
static constexpr char CLIENT1_TOKEN[] = "MacDaddy310";

static constexpr char CLIENT2_NAME[]  = "ShynetymeplayaTwo";
static constexpr char CLIENT2_TOKEN[] = "MacDaddy310";

static constexpr uint16_t CLIENT_REG_PORT = 42101;
static constexpr uint32_t CLIENT_TIMEOUT_MS = 15000;

/*
BLE UUID contract used by the ShyneTyme web controller.
*/
static constexpr char BLE_SERVICE_UUID[] =
    "78170001-7a32-4b19-913a-5354594d4501";
static constexpr char BLE_COMMAND_UUID[] =
    "78170002-7a32-4b19-913a-5354594d4501";
static constexpr char BLE_STATUS_UUID[] =
    "78170003-7a32-4b19-913a-5354594d4501";

#ifndef FX_MODE_2DSCROLLTEXT
#define FX_MODE_2DSCROLLTEXT 122
#endif

struct ShyneTymeCommand {
  char text[96];
};

struct RegisteredClient {
  const char* name;
  const char* token;
  IPAddress ip;
  uint32_t lastSeen;
  bool online;
};

class ShyneTymeHostUsermod;

class ShyneTymeBleCommandCallbacks : public BLECharacteristicCallbacks {
 private:
  ShyneTymeHostUsermod* owner;

 public:
  explicit ShyneTymeBleCommandCallbacks(ShyneTymeHostUsermod* pOwner)
      : owner(pOwner) {}

  void onWrite(BLECharacteristic* characteristic) override;
};

class ShyneTymeBleServerCallbacks : public BLEServerCallbacks {
 private:
  ShyneTymeHostUsermod* owner;

 public:
  explicit ShyneTymeBleServerCallbacks(ShyneTymeHostUsermod* pOwner)
      : owner(pOwner) {}

  void onConnect(BLEServer* server) override;
  void onDisconnect(BLEServer* server) override;
};

class ShyneTymeHostUsermod : public Usermod {
 private:
  BLEServer* bleServer = nullptr;
  BLECharacteristic* commandCharacteristic = nullptr;
  BLECharacteristic* statusCharacteristic = nullptr;
  QueueHandle_t commandQueue = nullptr;

  WiFiUDP clientRegistrationUdp;
  bool registrationUdpStarted = false;

  RegisteredClient clients[2] = {
      {CLIENT1_NAME, CLIENT1_TOKEN, IPAddress(), 0, false},
      {CLIENT2_NAME, CLIENT2_TOKEN, IPAddress(), 0, false},
  };

  String textBuffer;
  bool textTransactionActive = false;
  bool phoneBleConnected = false;
  String lastError = "0";

  static uint8_t clampByte(long value) {
    if (value < 0) return 0;
    if (value > 255) return 255;
    return static_cast<uint8_t>(value);
  }

  static String urlDecode(const String& input) {
    String out;
    out.reserve(input.length());

    for (size_t i = 0; i < input.length(); i++) {
      const char c = input[i];

      if (c == '%' && i + 2 < input.length()) {
        const char h1 = input[i + 1];
        const char h2 = input[i + 2];

        auto hexValue = [](char h) -> int {
          if (h >= '0' && h <= '9') return h - '0';
          if (h >= 'A' && h <= 'F') return h - 'A' + 10;
          if (h >= 'a' && h <= 'f') return h - 'a' + 10;
          return -1;
        };

        const int a = hexValue(h1);
        const int b = hexValue(h2);

        if (a >= 0 && b >= 0) {
          out += static_cast<char>((a << 4) | b);
          i += 2;
          continue;
        }
      }

      if (c == '+') out += ' ';
      else out += c;
    }

    return out;
  }

  static bool parseRgbHex(const String& text, uint32_t& color) {
    String value = text;
    value.trim();

    if (value.startsWith("#")) value.remove(0, 1);
    if (value.length() != 6) return false;

    for (size_t i = 0; i < value.length(); i++) {
      if (!isxdigit(static_cast<unsigned char>(value[i]))) return false;
    }

    color = strtoul(value.c_str(), nullptr, 16) & 0x00FFFFFFUL;
    return true;
  }

  void setHostNetworkRole() {
    /*
    WLED loads cfg.json before usermod setup(). Overwrite the runtime networking
    role here every boot so an old saved Wi-Fi setting cannot turn the host into
    a station by accident.

    Keep one default/unconfigured STA record because WLED expects multiWiFi[0].
    */
    if (multiWiFi.empty()) {
      multiWiFi.push_back(WiFiConfig(DEFAULT_CLIENT_SSID, ""));
    } else {
      multiWiFi.resize(1);
      multiWiFi[0] = WiFiConfig(DEFAULT_CLIENT_SSID, "");
    }

    strlcpy(apSSID, HOST_AP_SSID, sizeof(apSSID));
    strlcpy(apPass, HOST_AP_PASS, sizeof(apPass));      // WPA2 Password
    apBehavior = AP_BEHAVIOR_ALWAYS;   // host AP stays available
    apHide = 0;

    strlcpy(serverDescription, HOST_BLE_NAME, sizeof(serverDescription));
    strlcpy(cmDNS, "captain-shynetyme-worker", sizeof(cmDNS));

    /*
    HOST is authoritative:
    - send WLED sync
    - do not accept state sync back from clients
    */
    udpPort = 21324;
    syncGroups = 0x01;
    receiveGroups = 0x00;

    sendNotifications = true;
    sendNotificationsRT = true;
    notifyDirect = true;

    receiveNotificationBrightness = false;
    receiveNotificationColor = false;
    receiveNotificationEffects = false;
    receiveNotificationPalette = false;
    receiveSegmentOptions = false;
    receiveSegmentBounds = false;

    nodeBroadcastEnabled = false;
  }

  void setupBle() {
    commandQueue = xQueueCreate(12, sizeof(ShyneTymeCommand));
    if (!commandQueue) {
      lastError = "BLE_QUEUE";
      return;
    }

    BLEDevice::init(HOST_BLE_NAME);

    bleServer = BLEDevice::createServer();
    bleServer->setCallbacks(new ShyneTymeBleServerCallbacks(this));

    BLEService* service = bleServer->createService(BLE_SERVICE_UUID);

    commandCharacteristic = service->createCharacteristic(
        BLE_COMMAND_UUID,
        BLECharacteristic::PROPERTY_WRITE |
            BLECharacteristic::PROPERTY_WRITE_NR);

    statusCharacteristic = service->createCharacteristic(
        BLE_STATUS_UUID,
        BLECharacteristic::PROPERTY_READ);

    commandCharacteristic->setCallbacks(
        new ShyneTymeBleCommandCallbacks(this));

    updateStatusCharacteristic();

    service->start();

    BLEAdvertising* advertising = BLEDevice::getAdvertising();
    advertising->addServiceUUID(BLE_SERVICE_UUID);
    advertising->setScanResponse(true);
    advertising->start();
  }

  void startRegistrationUdpIfReady() {
    if (!apActive || registrationUdpStarted) return;

    registrationUdpStarted = clientRegistrationUdp.begin(CLIENT_REG_PORT);
    if (!registrationUdpStarted) lastError = "REG_UDP";
  }

  void handleClientRegistration() {
    if (!registrationUdpStarted) return;

    int packetSize = clientRegistrationUdp.parsePacket();

    while (packetSize > 0) {
      char buffer[128];
      const int readCount =
          clientRegistrationUdp.read(buffer, sizeof(buffer) - 1);

      if (readCount > 0) {
        buffer[readCount] = '\0';
        const String line(buffer);

        if (line.startsWith("HELLO|")) {
          const int first = line.indexOf('|');
          const int second = line.indexOf('|', first + 1);

          if (first >= 0 && second > first) {
            const String clientName = line.substring(first + 1, second);
            const String clientToken = line.substring(second + 1);

            bool accepted = false;

            for (auto& client : clients) {
              if (clientName == client.name &&
                  clientToken == client.token) {
                client.ip = clientRegistrationUdp.remoteIP();
                client.lastSeen = millis();
                client.online = true;
                accepted = true;
                break;
              }
            }

            if (!accepted) lastError = "CLIENT_AUTH";
          }
        }
      }

      packetSize = clientRegistrationUdp.parsePacket();
    }
  }

  void expireClients() {
    const uint32_t now = millis();

    for (auto& client : clients) {
      if (client.online &&
          static_cast<uint32_t>(now - client.lastSeen) >
              CLIENT_TIMEOUT_MS) {
        client.online = false;
      }
    }
  }

  void updateStatusCharacteristic() {
    if (!statusCharacteristic) return;

    String status;
    status.reserve(96);

    status += "HOST=1";
    status += ";BLE=";
    status += phoneBleConnected ? "1" : "0";
    status += ";C1=";
    status += clients[0].online ? "1" : "0";
    status += ";C2=";
    status += clients[1].online ? "1" : "0";
    status += ";ERR=";
    status += lastError;

    statusCharacteristic->setValue(status);
  }

  bool sendTextJsonToClient(const RegisteredClient& client,
                            const String& text) {
    if (!client.online) return false;

    HTTPClient http;

    String url = "http://";
    url += client.ip.toString();
    url += "/json/state";

    if (!http.begin(url)) return false;

    http.addHeader("Content-Type", "application/json");

    JsonDocument doc;
    JsonArray segments = doc["seg"].to<JsonArray>();
    JsonObject segment = segments.add<JsonObject>();

    segment["id"] = 0;
    segment["n"] = text;
    segment["fx"] = FX_MODE_2DSCROLLTEXT;

    String body;
    serializeJson(doc, body);

    const int code = http.POST(body);
    http.end();

    return code >= 200 && code < 300;
  }

  void applyText(const String& encodedText) {
    const String decoded = urlDecode(encodedText);

    Segment& seg = strip.getMainSegment();
    seg.setName(decoded);
    seg.setMode(FX_MODE_2DSCROLLTEXT);
    stateChanged = true;
    stateUpdated(CALL_MODE_DIRECT_CHANGE);

    bool allOnlineClientsSucceeded = true;
    bool anyOnlineClient = false;

    for (const auto& client : clients) {
      if (!client.online) continue;
      anyOnlineClient = true;

      if (!sendTextJsonToClient(client, decoded)) {
        allOnlineClientsSucceeded = false;
      }
    }

    if (anyOnlineClient && !allOnlineClientsSucceeded) lastError = "TEXT_HTTP";
    else lastError = "0";
  }

  void applyStateChange() {
    /*
    CALL_MODE_DIRECT_CHANGE makes WLED publish its native UDP sync packet because
    sendNotificationsRT + notifyDirect are forced on in setHostNetworkRole().
    */
    stateUpdated(CALL_MODE_DIRECT_CHANGE);
  }

  void processCommand(const String& incoming) {
    String command = incoming;
    command.trim();

    if (!command.length()) return;

    if (command == "STATUS") {
      lastError = "0";
      updateStatusCharacteristic();
      return;
    }

    if (command == "OFF") {
      bri = 0;
      applyStateChange();
      return;
    }

    if (command == "ON") {
      if (bri == 0) bri = briLast > 0 ? briLast : 128;
      applyStateChange();
      return;
    }

    if (command == "TXBEGIN") {
      textBuffer = "";
      textTransactionActive = true;
      lastError = "0";
      return;
    }

    if (command.startsWith("TX+=")) {
      if (!textTransactionActive) {
        lastError = "TEXT_STATE";
        return;
      }

      textBuffer += command.substring(4);

      if (textBuffer.length() > 640) {
        textBuffer.remove(640);
        lastError = "TEXT_LONG";
      }
      return;
    }

    if (command == "TXEND") {
      if (!textTransactionActive) {
        lastError = "TEXT_STATE";
        return;
      }

      textTransactionActive = false;
      applyText(textBuffer);
      return;
    }

    const int equals = command.indexOf('=');
    if (equals < 1) {
      lastError = "UNKNOWN";
      return;
    }

    const String key = command.substring(0, equals);
    const String value = command.substring(equals + 1);

    Segment& seg = strip.getMainSegment();

    if (key == "FXID") {
      seg.setMode(clampByte(value.toInt()));
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "BRI") {
      bri = clampByte(value.toInt());
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "SPD") {
      seg.speed = clampByte(value.toInt());
      stateChanged = true;
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "INT") {
      seg.intensity = clampByte(value.toInt());
      stateChanged = true;
      applyStateChange();
      lastError = "0";
      return;
    }

    /*
    WLED exposes custom effect sliders as c1/c2/c3. These map the existing
    ShyneTyme SIZE / DENSITY / TRAIL controls onto WLED's custom sliders.
    */
    if (key == "SIZE") {
      seg.custom1 = clampByte(value.toInt());
      stateChanged = true;
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "DENS") {
      seg.custom2 = clampByte(value.toInt());
      stateChanged = true;
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "TRAIL") {
      seg.custom3 =
          static_cast<uint8_t>(map(clampByte(value.toInt()), 0, 255, 0, 31));
      stateChanged = true;
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "DIR") {
      seg.setOption(SEG_OPTION_REVERSED, value == "REV");
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "MIRROR") {
      seg.setOption(SEG_OPTION_MIRROR, value.toInt() != 0);
      applyStateChange();
      lastError = "0";
      return;
    }

    uint32_t color = 0;

    if (key == "MAIN" && parseRgbHex(value, color)) {
      seg.setColor(0, color);
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "BG" && parseRgbHex(value, color)) {
      seg.setColor(1, color);
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "FG" && parseRgbHex(value, color)) {
      seg.setColor(2, color);
      applyStateChange();
      lastError = "0";
      return;
    }

    if (key == "PLOAD") {
      const int preset = value.toInt();

      if (preset >= 1 && preset <= 250) {
        applyPreset(static_cast<byte>(preset), CALL_MODE_DIRECT_CHANGE);
        lastError = "0";
      } else {
        lastError = "PRESET";
      }
      return;
    }

    /*
    Preset SAVE/DELETE is deliberately not faked here. WLED owns filesystem
    preset writes. We will wire those after the base host/client transport is
    hardware-verified.
    */
    if (key == "PSAVE" || key == "PDEL") {
      lastError = "PRESET_NI";
      return;
    }

    lastError = "UNKNOWN";
  }

  void processQueuedCommands() {
    if (!commandQueue) return;

    ShyneTymeCommand packet{};

    for (uint8_t i = 0; i < 6; i++) {
      if (xQueueReceive(commandQueue, &packet, 0) != pdTRUE) break;
      processCommand(String(packet.text));
    }
  }

 public:
  void setup() override {
    setHostNetworkRole();
    setupBle();
  }

  void loop() override {
    startRegistrationUdpIfReady();
    handleClientRegistration();
    expireClients();
    processQueuedCommands();
    updateStatusCharacteristic();
  }

  void enqueueBleCommand(const String& value) {
    if (!commandQueue || !value.length()) return;

    ShyneTymeCommand packet{};
    strlcpy(packet.text, value.c_str(), sizeof(packet.text));

    if (xQueueSend(commandQueue, &packet, 0) != pdTRUE) {
      lastError = "BLE_QUEUE_FULL";
    }
  }

  void setPhoneBleConnected(bool connected) {
    phoneBleConnected = connected;

    if (!connected) {
      BLEDevice::startAdvertising();
    }

    updateStatusCharacteristic();
  }

  void addToJsonInfo(JsonObject& root) override {
    JsonObject user = root["u"];
    if (user.isNull()) user = root["u"].to<JsonObject>();

    JsonArray role = user["ShyneTyme Host"].to<JsonArray>();
    role.add(phoneBleConnected ? "BLE phone connected" : "BLE waiting");
    role.add(clients[0].online ? " C1 online" : " C1 offline");
    role.add(clients[1].online ? " C2 online" : " C2 offline");
  }
};

void ShyneTymeBleCommandCallbacks::onWrite(
    BLECharacteristic* characteristic) {
  if (!owner || !characteristic) return;
  owner->enqueueBleCommand(characteristic->getValue());
}

void ShyneTymeBleServerCallbacks::onConnect(BLEServer* server) {
  (void)server;
  if (owner) owner->setPhoneBleConnected(true);
}

void ShyneTymeBleServerCallbacks::onDisconnect(BLEServer* server) {
  (void)server;
  if (owner) owner->setPhoneBleConnected(false);
}

static ShyneTymeHostUsermod shynetymeHostUsermod;
REGISTER_USERMOD(shynetymeHostUsermod);

#endif  // ARDUINO_ARCH_ESP32
